package com.studenttracker.database;
import java.sql.*; import java.nio.file.*;
public class DatabaseManager implements AutoCloseable { private final Connection connection; public DatabaseManager() throws SQLException { try{Files.createDirectories(Path.of("data"));}catch(Exception e){throw new SQLException("Cannot create data directory",e);} connection=DriverManager.getConnection("jdbc:sqlite:data/student_tracker.db"); init(); } public Connection getConnection(){return connection;} private void init() throws SQLException {try(Statement s=connection.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,subject TEXT NOT NULL,description TEXT,priority TEXT NOT NULL,deadline TEXT NOT NULL,estimated_hours REAL NOT NULL,status TEXT NOT NULL)");s.executeUpdate("CREATE TABLE IF NOT EXISTS study_sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,subject TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,minutes INTEGER NOT NULL)");}} public void close() throws SQLException{connection.close();} }
